(function(C){C["8a"]=(C["8a"]||[]).concat([{"q": "{3}. The set is not a cut. Which of the four properties fails first?", "a": "(iii): it is not closed downward", "w": ["(i): it has no member", "(ii): it misses no fraction", "(iv): it has a greatest member"], "why": "A cut is closed downward: with a member it holds every fraction below that member. This set leaves out fractions below one of its members."}, {"q": "Which set of fractions is a cut?", "a": "{s ∈ ℚ : s < 0 ∨ s² < 2}", "w": ["ℚ", "∅", "{s ∈ ℚ : s² < 2}"], "why": "A cut has a member, misses some fraction, is closed downward, and has no greatest member. The others fail: ℚ by (ii); {s ∈ ℚ : s² < 2} by (iii); ∅ by (i)."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["8b"]=(C["8b"]||[]).concat([{"q": "(7/4)* < (19/4)*. Which fraction is a witness: in (19/4)* and not in (7/4)*?", "a": "13/4", "w": ["5/4", "19/4", "61/12"], "why": "Witness-for-less: α < β exactly when some fraction is in β and not in α. 13/4 is below 19/4 and not below 7/4."}, {"q": "1* < (3/2)*. Which fraction is a witness: in (3/2)* and not in 1*?", "a": "1", "w": ["1/2", "3/2", "11/6"], "why": "Witness-for-less: α < β exactly when some fraction is in β and not in α. 1 is below 3/2 and not below 1: a fraction is not a member of its own cut."}, {"q": "(−1)* < (−1/3)*. Which fraction is a witness: in (−1/3)* and not in (−1)*?", "a": "−1", "w": ["−1/3", "0", "−3/2"], "why": "Witness-for-less: α < β exactly when some fraction is in β and not in α. −1 is below −1/3 and not below −1: a fraction is not a member of its own cut."}, {"q": "(−1/3)* < (2/3)*. Which fraction is a witness: in (2/3)* and not in (−1/3)*?", "a": "1/6", "w": ["2/3", "−5/6", "1"], "why": "Witness-for-less: α < β exactly when some fraction is in β and not in α. 1/6 is below 2/3 and not below −1/3."}, {"q": "1* < 2*. Which fraction is a witness: in 2* and not in 1*?", "a": "3/2", "w": ["7/3", "1/2", "2"], "why": "Witness-for-less: α < β exactly when some fraction is in β and not in α. 3/2 is below 2 and not below 1."}, {"q": "(−1)* < 0*. Which fraction is a witness: in 0* and not in (−1)*?", "a": "−1", "w": ["−3/2", "1/3", "0"], "why": "Witness-for-less: α < β exactly when some fraction is in β and not in α. −1 is below 0 and not below −1: a fraction is not a member of its own cut."}, {"q": "(−4/5)* < (−2/15)*. Which fraction is a witness: in (−2/15)* and not in (−4/5)*?", "a": "−4/5", "w": ["−13/10", "1/5", "−2/15"], "why": "Witness-for-less: α < β exactly when some fraction is in β and not in α. −4/5 is below −2/15 and not below −4/5: a fraction is not a member of its own cut."}, {"q": "(−1)* < (1/2)*. Which fraction is a witness: in (1/2)* and not in (−1)*?", "a": "−1/4", "w": ["5/6", "1/2", "−3/2"], "why": "Witness-for-less: α < β exactly when some fraction is in β and not in α. −1/4 is below 1/2 and not below −1."}, {"q": "(1/2)* < 2*. Which fraction is a witness: in 2* and not in (1/2)*?", "a": "1/2", "w": ["2", "0", "7/3"], "why": "Witness-for-less: α < β exactly when some fraction is in β and not in α. 1/2 is below 2 and not below 1/2: a fraction is not a member of its own cut."}, {"q": "(−1/2)* < 1*. Which fraction is a witness: in 1* and not in (−1/2)*?", "a": "1/4", "w": ["4/3", "1", "−1"], "why": "Witness-for-less: α < β exactly when some fraction is in β and not in α. 1/4 is below 1 and not below −1/2."}, {"q": "For reals α and β, how many of α < β, α = β, β < α hold?", "a": "exactly one", "w": ["at most one, perhaps none", "at least one, perhaps two", "all three, when α = β"], "why": "Three-way-order on ℝ. At least one, by any-two-compare; no two together, since ⊆ both ways is sameness."}, {"q": "On the line, what does α ≤ β mean?", "a": "α ⊆ β: every fraction in α is in β", "w": ["some fraction is in α and not in β", "β ⊆ α", "α has fewer members than β"], "why": "Order is being a part of. And α < β means α ≤ β and α ≠ β."}, {"q": "The proof of any-two-compare on ℝ cites either-way. Could a cleverer column avoid it?", "a": "no: the comparison is exactly as strong as the either-way principle", "w": ["yes: by the choosing axiom alone", "yes: by finite-search", "nobody knows"], "why": "Comparing-gives-either-way: if any two reals compare, then P ∨ ¬P, for any statement P."}, {"q": "{0} and {1} are parts of ℚ, and neither is a part of the other. Does that refute any-two-compare on ℝ?", "a": "no: neither set is a cut, and the technique speaks of reals", "w": ["yes, unless either-way is dropped", "yes: any two sets of fractions compare", "no: {0} is a part of {1}"], "why": "Of any two cuts, one is a part of the other. Closed downward is what makes it so."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["8c"]=(C["8c"]||[]).concat([{"q": "Is sup S always a member of S?", "a": "sometimes: for {1*, 2*, 3*} yes, for the cuts of 1 − 1/n no", "w": ["only when S is infinite", "always", "never"], "why": "No member of {(1 − 1/n)*} reaches 1*, and 1* is the least real above them all."}, {"q": "To show σ = sup S without writing the union, what two things are shown?", "a": "σ is an upper bound of S, and nothing smaller is", "w": ["σ is above one member of S, and below another", "σ is a fraction, and S is finite", "σ is in S, and σ is positive"], "why": "A least upper bound is an upper bound that is at most every upper bound."}, {"q": "Why is ⋃{n* : n ∈ ℕ} not a real?", "a": "it misses no fraction: the set has no upper bound", "w": ["it has no member", "it is not closed downward", "it has a greatest member"], "why": "Union-of-cuts needs a member and an upper bound. Without the bound the union is all of ℚ, and (ii) fails."}, {"q": "The hole’s heap has fractions above it: 3/2 and 2. Has it a least upper bound among the fractions?", "a": "no: below any fraction bound there is a smaller one", "w": ["yes: 2", "yes: 3/2", "yes: 7/5"], "why": "The fractions are not complete. On the line the same heap is a real, and it is its own least upper bound."}, {"q": "What does no-holes say?", "a": "every set of reals with a member and an upper bound has a least upper bound, and it is the union", "w": ["every set of reals has a greatest member", "every real is a fraction’s cut", "every set of fractions has a least upper bound among the fractions"], "why": "sup S = ⋃S. The union of the cuts is itself a cut, and nothing smaller is above them all."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["8d"]=(C["8d"]||[]).concat([{"q": "Cuts have no representatives. How is each operation on cuts built?", "a": "as a sift of ℚ, which then has to be checked to be a cut", "w": ["on a representative, checking the choice does not matter", "by recursion on the numbers", "by the choosing axiom"], "why": "A cut is one set. So α + β is {r + s : r ∈ α, s ∈ β}, and the four properties are checked for it."}, {"q": "The tempting −α is the negatives of the fractions α misses. Why is it wrong?", "a": "for α = r* it has a greatest member, −r: (iv) fails", "w": ["it is all of ℚ", "it has no member", "it is not closed downward"], "why": "The cure is to ask for room: the negatives of the fractions with some missed fraction below them."}, {"q": "For positive cuts α and β, the products rs of positive r ∈ α and s ∈ β are gathered. What else must be let in?", "a": "every fraction at most 0", "w": ["every fraction below 1", "the fractions α and β both miss", "nothing"], "why": "The positive products alone would miss the negatives, and the set would not be closed downward."}, {"q": "What is a complete ordered field?", "a": "a regular number system with an order that agrees with its arithmetic, and no holes", "w": ["a number system where every member is a fraction", "the fractions with their order", "any set with an adding and a multiplying"], "why": "ℝ, with its + and ·, 0 and 1, negatives, reciprocals and positive, is one. ℚ is ordered and regular, and has holes."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["8f"]=(C["8f"]||[]).concat([{"q": "For every real x, what can be said of x²?", "a": "0 ≤ x²", "w": ["0 < x²", "x ≤ x²", "x² ≤ x"], "why": "Square-never-negative. A positive times a positive and a negative times a negative are both positive, and 0² = 0."}, {"q": "Two expressions with roots are to be shown the same. What does the uniqueness method ask?", "a": "that both are non-negative and have the same square", "w": ["that both are fractions", "that their difference is small", "that one is the square of the other"], "why": "One-root: for non-negative x and y, x² = y² gives x = y."}, {"q": "Is {r ∈ ℚ : r² < 2} the real √2?", "a": "no: it is not a cut, and √2 lets the negatives in", "w": ["no: √2 is a fraction", "yes", "no: it has a greatest member"], "why": "It leaves out −2, which is below its member 0. The hole’s cut is {r ∈ ℚ : r < 0 ∨ r² < 2}."}, {"q": "A real with a given square is wanted. How does the line supply it?", "a": "as the least upper bound of what falls short", "w": ["by the choosing axiom", "as the greatest fraction that falls short", "by trying fractions until one fits"], "why": "S = {x : 0 ≤ x ∧ x² < 2} has a member and an upper bound, so no-holes gives σ = sup S. Too small and too big are both refuted, so σ² = 2."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["8h"]=(C["8h"]||[]).concat([{"q": "|a + b| = |a| + |b|. For which pair does the line hold?", "a": "a = 2, b = 8", "w": ["a = 4, b = −8", "a = 8, b = −7", "a = −4, b = 6"], "why": "Triangle: |a + b| ≤ |a| + |b|, always. The two sides are the same when a and b have the same sign, and the left is smaller when the signs differ. Here |2 + 8| = 10 and |a| + |b| = 10."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
